import React, { useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowLeft, faBuildingColumns, faCalendarDays, faIndianRupeeSign, faReceipt } from "@fortawesome/free-solid-svg-icons";
import Axios from "../../Axios";

const money = (value) => `₹${Number(value || 0).toLocaleString("en-IN")}`;
const statusStyle = { paid: "bg-emerald-50 text-emerald-700 ring-emerald-200", partial: "bg-amber-50 text-amber-700 ring-amber-200", pending: "bg-rose-50 text-rose-700 ring-rose-200" };
const Status = ({ value }) => <span className={`rounded-full px-3 py-1 text-xs font-bold capitalize ring-1 ${statusStyle[value] || statusStyle.pending}`}>{value || "pending"}</span>;

export default function FeeCentreDetails() {
  const { centreId } = useParams();
  const [data, setData] = useState(null);
  const [error, setError] = useState("");
  useEffect(() => { Axios.get(`/fee-collection/centre/${centreId}`).then(({ data: response }) => setData(response)).catch((e) => setError(e.response?.data?.message || "Unable to load this centre's fee details.")); }, [centreId]);
  const totals = useMemo(() => (data?.statements || []).reduce((result, item) => ({ due: result.due + item.totalDue, paid: result.paid + item.paid }), { due: 0, paid: 0 }), [data]);
  if (error) return <main className="min-h-full bg-[#f4f7fb] p-8"><div className="mx-auto max-w-3xl rounded-3xl border border-rose-200 bg-rose-50 p-6 text-rose-800"><h1 className="font-bold">Unable to load fee details</h1><p className="mt-1 text-sm">{error}</p><Link to="/fee-collection" className="mt-4 inline-block font-bold text-indigo-700">Back to fee collection</Link></div></main>;
  if (!data) return <main className="min-h-full bg-[#f4f7fb] p-8"><div className="mx-auto max-w-6xl animate-pulse"><div className="h-8 w-56 rounded bg-slate-200" /><div className="mt-6 h-40 rounded-3xl bg-white/70" /></div></main>;
  return <main className="min-h-full overflow-hidden bg-[#f4f7fb] p-5 md:p-8 xl:p-10"><div className="pointer-events-none fixed inset-0"><div className="absolute -left-24 top-0 h-80 w-80 rounded-full bg-indigo-300/20 blur-3xl" /></div><div className="relative mx-auto max-w-6xl"><Link to="/fee-collection" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-indigo-700 hover:text-indigo-900"><FontAwesomeIcon icon={faArrowLeft} /> Back to fee collection</Link><section className="rounded-[28px] border border-white/80 bg-white/65 p-6 shadow-[0_18px_60px_rgba(31,38,135,.09)] backdrop-blur-xl md:p-8"><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div className="flex items-center gap-4"><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-600 text-white shadow-lg shadow-indigo-600/20"><FontAwesomeIcon icon={faBuildingColumns} size="lg" /></div><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Study centre fee profile</p><h1 className="mt-1 text-2xl font-black tracking-tight">{data.studyCentre?.studyCentreName}</h1><p className="mt-1 text-sm text-slate-500">{data.studyCentre?.studyCentreCode} · {data.studyCentre?.district || "Location not provided"}</p></div></div><div className="grid grid-cols-2 gap-3 text-center md:text-right"><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Total due</p><p className="mt-1 text-xl font-black">{money(totals.due)}</p></div><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Outstanding</p><p className="mt-1 text-xl font-black text-amber-600">{money(totals.due - totals.paid)}</p></div></div></div></section><div className="mt-6 space-y-5">{data.statements.map((statement) => <section key={statement._id} className="overflow-hidden rounded-[28px] border border-white/80 bg-white/65 shadow-[0_18px_60px_rgba(31,38,135,.08)] backdrop-blur-xl"><div className="flex flex-col justify-between gap-3 border-b border-slate-200/70 p-5 md:flex-row md:items-center md:p-6"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600"><FontAwesomeIcon icon={faCalendarDays} /></div><div><h2 className="font-extrabold">Academic year {statement.academicYear}</h2><p className="text-xs text-slate-500">Calculated {new Date(statement.calculatedAt).toLocaleDateString("en-IN")}</p></div></div><Status value={statement.status} /></div><div className="grid gap-4 p-5 md:grid-cols-4 md:p-6"><div className="rounded-2xl bg-slate-50/80 p-4"><p className="text-xs font-bold uppercase text-slate-500">Active students</p><p className="mt-2 text-2xl font-black">{statement.studentCount}</p></div><div className="rounded-2xl bg-slate-50/80 p-4"><p className="text-xs font-bold uppercase text-slate-500">Affiliation fee</p><p className="mt-2 text-2xl font-black">{money(statement.affiliationFee)}</p></div><div className="rounded-2xl bg-slate-50/80 p-4"><p className="text-xs font-bold uppercase text-slate-500">Student fee</p><p className="mt-2 text-2xl font-black">{money(statement.studentCount * statement.perStudentFee)}</p><p className="mt-1 text-xs text-slate-500">{money(statement.perStudentFee)} per student</p></div><div className="rounded-2xl bg-indigo-50/80 p-4"><p className="text-xs font-bold uppercase text-indigo-600">Total due</p><p className="mt-2 text-2xl font-black text-indigo-700">{money(statement.totalDue)}</p></div></div><div className="border-t border-slate-200/70 p-5 md:p-6"><div className="mb-3 flex items-center gap-2"><FontAwesomeIcon icon={faReceipt} className="text-slate-400" /><h3 className="text-sm font-extrabold">Payment history</h3><span className="ml-auto text-sm font-bold text-emerald-600">Paid {money(statement.paid)}</span></div>{statement.payments.length ? <div className="divide-y divide-slate-200/70">{statement.payments.map((payment) => <div key={payment._id} className="flex flex-col gap-1 py-3 text-sm sm:flex-row sm:items-center sm:justify-between"><div><span className="font-bold">{money(payment.amount)}</span><span className="ml-2 text-slate-500">{payment.method} · {new Date(payment.paidOn).toLocaleDateString("en-IN")}</span>{payment.reference && <span className="ml-2 text-xs text-slate-400">Ref: {payment.reference}</span>}</div>{payment.notes && <span className="text-xs italic text-slate-500">{payment.notes}</span>}</div>)}</div> : <p className="text-sm text-slate-500">No payments recorded for this academic year.</p>}<div className="mt-4 flex justify-between border-t border-slate-200/70 pt-4 text-sm"><span className="font-bold text-slate-500">Outstanding balance</span><strong className="text-amber-600">{money(statement.outstanding)}</strong></div></div></section>)}</div></div></main>;
}
