import React, { useEffect, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowTrendDown, faCalendarDays, faCircleCheck, faClock, faIndianRupeeSign, faReceipt } from "@fortawesome/free-solid-svg-icons";
import Axios from "../../Axios";

const money = (value) => `₹${Number(value || 0).toLocaleString("en-IN")}`;
const statusStyle = { paid: "bg-emerald-50 text-emerald-700 ring-emerald-200", partial: "bg-amber-50 text-amber-700 ring-amber-200", pending: "bg-rose-50 text-rose-700 ring-rose-200" };
export default function FeeStatus() {
  const [record, setRecord] = useState(undefined); const [error, setError] = useState("");
  useEffect(() => { Axios.get("/fee-collection/my-status").then(({ data }) => setRecord(data)).catch((e) => { setError(e.response?.data?.message || "Unable to load your fee statement."); setRecord(null); }); }, []);
  if (record === undefined) return <div className="min-h-full bg-[#f4f7fb] p-8"><div className="mx-auto max-w-5xl animate-pulse"><div className="h-9 w-64 rounded bg-slate-200" /><div className="mt-6 h-44 rounded-3xl bg-white/70" /></div></div>;
  if (!record) return <main className="min-h-full bg-[#f4f7fb] p-5 md:p-8"><div className="mx-auto max-w-3xl rounded-[28px] border border-white/80 bg-white/70 p-8 text-center shadow-xl backdrop-blur-xl"><div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600"><FontAwesomeIcon icon={faReceipt} size="lg" /></div><h1 className="text-xl font-black">No fee statement available</h1><p className="mt-2 text-sm text-slate-500">{error || "Your centre's statement will appear here after the Super Admin publishes the annual schedule."}</p></div></main>;
  const paid = record.paid || 0; const percent = record.totalDue ? Math.min(Math.round((paid / record.totalDue) * 100), 100) : 0;
  return <main className="min-h-full overflow-hidden bg-[#f4f7fb] p-5 md:p-8"><div className="pointer-events-none fixed inset-0"><div className="absolute -left-20 top-0 h-80 w-80 rounded-full bg-indigo-300/20 blur-3xl" /><div className="absolute right-0 top-1/3 h-80 w-80 rounded-full bg-cyan-200/20 blur-3xl" /></div><div className="relative mx-auto max-w-6xl"><header className="mb-7"><div className="mb-3 inline-flex items-center gap-2 rounded-full border border-indigo-100 bg-white/60 px-3 py-1.5 text-xs font-bold text-indigo-700 shadow-sm backdrop-blur"><FontAwesomeIcon icon={faCalendarDays} /> {record.academicYear}</div><h1 className="text-3xl font-black tracking-tight text-slate-900">Fee statement</h1><p className="mt-2 text-sm text-slate-500">{record.studyCentre?.studyCentreName} · {record.studyCentre?.studyCentreCode}</p></header><section className="rounded-[30px] border border-white/80 bg-gradient-to-br from-indigo-600 to-violet-700 p-6 text-white shadow-xl shadow-indigo-900/15 md:p-8"><div className="flex flex-col justify-between gap-8 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-indigo-200">Outstanding balance</p><p className="mt-2 text-4xl font-black tracking-tight">{money(record.outstanding)}</p><p className="mt-2 text-sm text-indigo-100">{percent}% of the annual fee has been received</p></div><div className="w-full max-w-sm"><div className="mb-2 flex justify-between text-xs font-bold text-indigo-100"><span>Paid {money(paid)}</span><span>Total {money(record.totalDue)}</span></div><div className="h-3 overflow-hidden rounded-full bg-white/20"><div className="h-full rounded-full bg-white transition-all" style={{ width: `${percent}%` }} /></div></div></div></section><section className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div className="rounded-3xl border border-white/80 bg-white/65 p-5 shadow-sm backdrop-blur-xl"><FontAwesomeIcon icon={faIndianRupeeSign} className="text-indigo-600" /><p className="mt-5 text-xs font-bold uppercase tracking-wider text-slate-500">Total due</p><p className="mt-1 text-2xl font-black">{money(record.totalDue)}</p></div><div className="rounded-3xl border border-white/80 bg-white/65 p-5 shadow-sm backdrop-blur-xl"><FontAwesomeIcon icon={faCircleCheck} className="text-emerald-600" /><p className="mt-5 text-xs font-bold uppercase tracking-wider text-slate-500">Paid</p><p className="mt-1 text-2xl font-black text-emerald-600">{money(paid)}</p></div><div className="rounded-3xl border border-white/80 bg-white/65 p-5 shadow-sm backdrop-blur-xl"><FontAwesomeIcon icon={faArrowTrendDown} className="text-amber-600" /><p className="mt-5 text-xs font-bold uppercase tracking-wider text-slate-500">Outstanding</p><p className="mt-1 text-2xl font-black text-amber-600">{money(record.outstanding)}</p></div><div className="rounded-3xl border border-white/80 bg-white/65 p-5 shadow-sm backdrop-blur-xl"><FontAwesomeIcon icon={faClock} className="text-violet-600" /><p className="mt-5 text-xs font-bold uppercase tracking-wider text-slate-500">Active students</p><p className="mt-1 text-2xl font-black">{record.studentCount}</p></div></section><section className="mt-6 rounded-[30px] border border-white/80 bg-white/65 p-5 shadow-[0_18px_60px_rgba(31,38,135,.08)] backdrop-blur-xl md:p-7"><div className="flex items-center justify-between"><div><h2 className="font-black">Payment history</h2><p className="mt-1 text-xs text-slate-500">Every payment recorded against this statement.</p></div><span className={`rounded-full px-3 py-1 text-xs font-bold capitalize ring-1 ${statusStyle[record.status] || statusStyle.pending}`}>{record.status}</span></div>{record.payments?.length ? <div className="mt-5 divide-y divide-slate-200/70">{record.payments.map((payment) => <div key={payment._id} className="flex flex-col gap-2 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold">{money(payment.amount)} <span className="ml-2 text-xs font-medium capitalize text-slate-500">{payment.method}</span></p><p className="mt-1 text-xs text-slate-400">{new Date(payment.paidOn).toLocaleDateString("en-IN")}{payment.reference ? ` · Ref ${payment.reference}` : ""}</p></div>{payment.notes && <p className="text-xs italic text-slate-500">{payment.notes}</p>}</div>)}</div> : <div className="mt-6 rounded-2xl bg-slate-50/80 p-6 text-center text-sm text-slate-500">No payments have been recorded yet.</div>}</section></div></main>;
}
