import React, { useCallback, useEffect, useMemo, useState } from "react";
import Axios from "../../Axios";
import { toast } from "react-toastify";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowTrendDown, faArrowTrendUp, faBuildingColumns, faCalendarDays, faIndianRupeeSign, faPlus, faReceipt, faRotate } from "@fortawesome/free-solid-svg-icons";

const money = (value) => `₹${Number(value || 0).toLocaleString("en-IN")}`;
const statusStyle = { paid: "bg-emerald-50 text-emerald-700 ring-emerald-200", partial: "bg-amber-50 text-amber-700 ring-amber-200", pending: "bg-rose-50 text-rose-700 ring-rose-200" };
const Status = ({ value }) => <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold capitalize ring-1 ${statusStyle[value] || statusStyle.pending}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{value || "pending"}</span>;

function Stat({ label, value, icon, tone, detail }) { return <div className="relative overflow-hidden rounded-3xl border border-white/70 bg-white/65 p-5 shadow-[0_12px_40px_rgba(31,38,135,.08)] backdrop-blur-xl"><div className={`mb-6 flex h-10 w-10 items-center justify-center rounded-2xl ${tone}`}><FontAwesomeIcon icon={icon} /></div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-slate-500">{label}</p><p className="mt-1 text-2xl font-black tracking-tight text-slate-900">{value}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></div>; }

export default function FeeCollection() {
  const [year, setYear] = useState("");
  const [rate, setRate] = useState({ affiliationFee: "", perStudentFee: "" });
  const [data, setData] = useState({ rates: [], collections: [] });
  const [payment, setPayment] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => { setLoading(true); setError(""); try { const { data: response } = await Axios.get(`/fee-collection${year ? `?academicYear=${encodeURIComponent(year)}` : ""}`); setData(response); } catch (e) { setError(e.response?.data?.message || "We couldn't load the fee ledger. Please refresh and try again."); } finally { setLoading(false); } }, [year]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => { document.querySelectorAll("tbody td:first-child").forEach((cell, index) => { const row = data.collections[index]; if (!row?.studyCentre?._id) return; cell.style.cursor = "pointer"; cell.title = "Open fee details"; cell.onclick = () => { window.location.href = `/fee-collection/centre/${row.studyCentre._id}`; }; }); }, [data.collections]);
  const totals = useMemo(() => data.collections.reduce((result, row) => { const paid = row.payments?.reduce((sum, item) => sum + item.amount, 0) || 0; return { due: result.due + row.totalDue, paid: result.paid + paid }; }, { due: 0, paid: 0 }), [data]);

  const saveRate = async (event) => { event.preventDefault(); setError(""); if (!/^\d{4}-\d{2,4}$/.test(year.trim())) return setError("Enter a valid academic year, for example 2026-27."); if (Number(rate.affiliationFee) < 0 || Number(rate.perStudentFee) < 0 || rate.affiliationFee === "" || rate.perStudentFee === "") return setError("Enter both fee amounts as zero or a positive number."); setSaving(true); try { await Axios.post("/fee-collection/rates", { academicYear: year.trim(), affiliationFee: Number(rate.affiliationFee), perStudentFee: Number(rate.perStudentFee) }); await Axios.post("/fee-collection/calculate", { academicYear: year.trim() }); toast.success("Fee schedule published"); await load(); } catch (e) { setError(e.response?.data?.message || "The fee schedule could not be published. Check your connection and try again."); } finally { setSaving(false); } };
  const savePayment = async (event) => { event.preventDefault(); const amount = Number(payment.form.amount); if (!amount || amount <= 0) return setPayment({ ...payment, error: "Enter a payment amount greater than zero." }); setPayment({ ...payment, saving: true, error: "" }); try { await Axios.post(`/fee-collection/${payment._id}/payments`, { ...payment.form, amount }); toast.success("Payment recorded successfully"); setPayment(null); await load(); } catch (e) { setPayment({ ...payment, saving: false, error: e.response?.data?.message || "Payment could not be recorded. Please try again." }); } };
  const updateRate = (key, value) => setRate((current) => ({ ...current, [key]: value }));

  return <div className="min-h-full overflow-hidden bg-[#f4f7fb] text-slate-900"><div className="pointer-events-none fixed inset-0 overflow-hidden"><div className="absolute -left-32 -top-32 h-96 w-96 rounded-full bg-indigo-300/20 blur-3xl" /><div className="absolute right-0 top-1/3 h-96 w-96 rounded-full bg-cyan-200/20 blur-3xl" /></div><main className="relative mx-auto max-w-[1500px] p-5 md:p-8 xl:p-10">
    <header className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><div className="mb-3 inline-flex items-center gap-2 rounded-full border border-indigo-100 bg-white/60 px-3 py-1.5 text-xs font-bold text-indigo-700 shadow-sm backdrop-blur"><span className="h-2 w-2 rounded-full bg-emerald-500 shadow-[0_0_0_4px_rgba(16,185,129,.15)]" />Finance workspace</div><h1 className="text-3xl font-black tracking-tight md:text-4xl">Fee collection</h1><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">Publish fee schedules, monitor centre balances, and keep every instalment traceable.</p></div><button onClick={load} disabled={loading} className="inline-flex items-center justify-center gap-2 rounded-2xl border border-white/80 bg-white/65 px-4 py-2.5 text-sm font-bold text-slate-700 shadow-sm backdrop-blur transition hover:bg-white disabled:opacity-60"><FontAwesomeIcon icon={faRotate} spin={loading} /> Refresh ledger</button></header>
    {error && <div role="alert" className="mb-6 flex items-start gap-3 rounded-2xl border border-rose-200 bg-rose-50/80 px-4 py-3 text-sm text-rose-800 shadow-sm"><span className="mt-0.5 font-black">!</span><div><p className="font-bold">Something needs your attention</p><p className="mt-0.5 text-rose-700">{error}</p></div></div>}
    <section className="mb-7 rounded-[28px] border border-white/80 bg-white/60 p-5 shadow-[0_18px_60px_rgba(31,38,135,.09)] backdrop-blur-xl md:p-6"><div className="mb-5 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-indigo-600 text-white shadow-lg shadow-indigo-600/20"><FontAwesomeIcon icon={faCalendarDays} /></div><div><h2 className="font-extrabold">Publish a fee schedule</h2><p className="text-xs text-slate-500">Rates are saved by academic year and do not rewrite past ledgers.</p></div></div><form onSubmit={saveRate} className="grid gap-4 lg:grid-cols-[1.1fr_1fr_1fr_auto] lg:items-end"><label className="text-xs font-bold uppercase tracking-wider text-slate-500">Academic year<input value={year} onChange={(e) => setYear(e.target.value)} placeholder="2026-27" className="mt-2 w-full rounded-2xl border border-slate-200 bg-white/70 px-4 py-3 text-sm font-semibold outline-none transition placeholder:text-slate-300 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100" /></label><label className="text-xs font-bold uppercase tracking-wider text-slate-500">Affiliation fee<input type="number" min="0" value={rate.affiliationFee} onChange={(e) => updateRate("affiliationFee", e.target.value)} placeholder="Fixed amount" className="mt-2 w-full rounded-2xl border border-slate-200 bg-white/70 px-4 py-3 text-sm font-semibold outline-none transition placeholder:text-slate-300 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100" /></label><label className="text-xs font-bold uppercase tracking-wider text-slate-500">Per active student<input type="number" min="0" value={rate.perStudentFee} onChange={(e) => updateRate("perStudentFee", e.target.value)} placeholder="Student rate" className="mt-2 w-full rounded-2xl border border-slate-200 bg-white/70 px-4 py-3 text-sm font-semibold outline-none transition placeholder:text-slate-300 focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100" /></label><button disabled={saving} className="inline-flex h-[47px] items-center justify-center gap-2 rounded-2xl bg-indigo-600 px-6 text-sm font-bold text-white shadow-lg shadow-indigo-600/25 transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-60"><FontAwesomeIcon icon={saving ? faRotate : faPlus} spin={saving} />{saving ? "Publishing…" : "Publish schedule"}</button></form></section>
    <section className="mb-7 grid gap-4 md:grid-cols-3"><Stat label="Centre dues" value={money(totals.due)} detail={`${data.collections.length} centre${data.collections.length === 1 ? "" : "s"} in ledger`} icon={faIndianRupeeSign} tone="bg-indigo-100 text-indigo-600" /><Stat label="Collected" value={money(totals.paid)} detail={totals.due ? `${Math.round((totals.paid / totals.due) * 100)}% of total dues` : "No payments yet"} icon={faArrowTrendUp} tone="bg-emerald-100 text-emerald-600" /><Stat label="Outstanding" value={money(totals.due - totals.paid)} detail="Balance to follow up" icon={faArrowTrendDown} tone="bg-amber-100 text-amber-600" /></section>
    <section className="overflow-hidden rounded-[28px] border border-white/80 bg-white/65 shadow-[0_18px_60px_rgba(31,38,135,.09)] backdrop-blur-xl"><div className="flex flex-col justify-between gap-3 border-b border-slate-200/70 p-5 md:flex-row md:items-center md:p-6"><div><h2 className="font-extrabold">Centre ledger</h2><p className="mt-1 text-xs text-slate-500">Active students exclude deleted and dropped-out records.</p></div>{year && <span className="rounded-full bg-indigo-50 px-3 py-1.5 text-xs font-bold text-indigo-700">Academic year · {year}</span>}</div>{loading ? <div className="space-y-3 p-6">{[1, 2, 3].map((item) => <div key={item} className="h-16 animate-pulse rounded-2xl bg-slate-100/80" />)}</div> : data.collections.length === 0 ? <div className="p-12 text-center"><div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-500"><FontAwesomeIcon icon={faReceipt} size="lg" /></div><h3 className="font-bold">No centre dues yet</h3><p className="mx-auto mt-1 max-w-sm text-sm text-slate-500">Publish a schedule for an academic year to generate the centre ledger.</p></div> : <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-slate-50/70 text-[10px] font-bold uppercase tracking-wider text-slate-500"><tr><th className="px-6 py-4">Study centre</th><th className="px-4 py-4">Students</th><th className="px-4 py-4">Due</th><th className="px-4 py-4">Paid</th><th className="px-4 py-4">Status</th><th className="px-6 py-4 text-right">Action</th></tr></thead><tbody>{data.collections.map((row) => { const paid = row.payments?.reduce((sum, item) => sum + item.amount, 0) || 0; return <tr key={row._id} className="border-t border-slate-200/60 transition hover:bg-indigo-50/30"><td className="px-6 py-5"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-100 text-slate-500"><FontAwesomeIcon icon={faBuildingColumns} /></div><div><p className="text-sm font-bold text-slate-800">{row.studyCentre?.studyCentreName || "Unknown centre"}</p><p className="mt-0.5 text-xs text-slate-400">{row.studyCentre?.studyCentreCode || "No centre code"}</p></div></div></td><td className="px-4 py-5 text-sm font-semibold">{row.studentCount}</td><td className="px-4 py-5 text-sm font-bold">{money(row.totalDue)}</td><td className="px-4 py-5 text-sm font-bold text-emerald-600">{money(paid)}</td><td className="px-4 py-5"><Status value={row.status} /></td><td className="px-6 py-5 text-right"><button onClick={() => setPayment({ _id: row._id, form: { amount: "", method: "bank", reference: "", notes: "" }, error: "" })} className="rounded-xl bg-indigo-50 px-3 py-2 text-xs font-bold text-indigo-700 transition hover:bg-indigo-100">Record payment</button></td></tr>; })}</tbody></table></div>}</section>
  </main>{payment && <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/45 p-4 backdrop-blur-sm"><form onSubmit={savePayment} className="w-full max-w-md rounded-[28px] border border-white/80 bg-white/90 p-6 shadow-2xl backdrop-blur-xl"><div className="mb-6 flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Ledger update</p><h2 className="mt-1 text-xl font-black">Record payment</h2></div><button type="button" onClick={() => setPayment(null)} className="rounded-xl px-3 py-1 text-xl text-slate-400 hover:bg-slate-100">×</button></div>{payment.error && <div role="alert" className="mb-4 rounded-xl bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700">{payment.error}</div>}<label className="text-xs font-bold uppercase tracking-wider text-slate-500">Amount<input autoFocus required type="number" min="1" value={payment.form.amount} onChange={(e) => setPayment({ ...payment, form: { ...payment.form, amount: e.target.value } })} placeholder="Enter amount" className="mt-2 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100" /></label><div className="mt-4 grid grid-cols-2 gap-3"><label className="text-xs font-bold uppercase tracking-wider text-slate-500">Method<select value={payment.form.method} onChange={(e) => setPayment({ ...payment, form: { ...payment.form, method: e.target.value } })} className="mt-2 w-full rounded-2xl border border-slate-200 bg-white px-3 py-3 text-sm font-semibold outline-none focus:border-indigo-400"><option>bank</option><option>upi</option><option>cash</option><option>cheque</option><option>other</option></select></label><label className="text-xs font-bold uppercase tracking-wider text-slate-500">Reference<input value={payment.form.reference} onChange={(e) => setPayment({ ...payment, form: { ...payment.form, reference: e.target.value } })} placeholder="Optional" className="mt-2 w-full rounded-2xl border border-slate-200 bg-white px-3 py-3 text-sm font-semibold outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100" /></label></div><label className="mt-4 block text-xs font-bold uppercase tracking-wider text-slate-500">Notes<textarea rows="3" value={payment.form.notes} onChange={(e) => setPayment({ ...payment, form: { ...payment.form, notes: e.target.value } })} placeholder="Add a note for the audit trail" className="mt-2 w-full resize-none rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none focus:border-indigo-400 focus:ring-4 focus:ring-indigo-100" /></label><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={() => setPayment(null)} className="rounded-2xl px-4 py-3 text-sm font-bold text-slate-500 hover:bg-slate-100">Cancel</button><button disabled={payment.saving} className="rounded-2xl bg-indigo-600 px-5 py-3 text-sm font-bold text-white shadow-lg shadow-indigo-600/25 hover:bg-indigo-700 disabled:opacity-60">{payment.saving ? "Saving…" : "Save payment"}</button></div></form></div>}</div>;
}
